<?php
if(!defined('APP_ENTRY_POINT')){http_response_code(404);exit;}
$root=dirname(__DIR__,4);require_once $root.'/auth.php';checkPermission('manage_helpers');require_once $root.'/db_connection.php';
$db=(new Database())->getConnection();$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
function hh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$actionId=(int)($_GET['aktion']??0);
$q=$db->prepare('SELECT * FROM helper_actions WHERE id=?');$q->execute([$actionId]);$action=$q->fetch(PDO::FETCH_ASSOC);
$stations=[];$days=[];$openTotal=0;$requiredTotal=0;
if($action){
 $q=$db->prepare('SELECT * FROM helper_stations WHERE action_id=? ORDER BY sort_order,id');$q->execute([$actionId]);$stations=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare('SELECT * FROM helper_days WHERE action_id=? ORDER BY event_date');$q->execute([$actionId]);$days=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT a.day_id,a.station_id,a.slot_key,r.full_name,r.email FROM helper_assignments a JOIN helper_registrations r ON r.id=a.registration_id AND r.status='active' WHERE r.action_id=? ORDER BY r.full_name");$q->execute([$actionId]);$filled=[];
 foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){$key=$r['day_id'].'|'.$r['station_id'].'|'.$r['slot_key'];if(!isset($filled[$key]))$filled[$key]=['count'=>0,'people'=>[]];$filled[$key]['count']++;$filled[$key]['people'][]=$r['full_name']."\t".$r['email'];}
 foreach($filled as &$filledCell)$filledCell['people']=implode("\n",$filledCell['people']);unset($filledCell);
 $q=$db->prepare('SELECT day_id,station_id,active_slots_json FROM helper_day_stations WHERE station_id IN (SELECT id FROM helper_stations WHERE action_id=?)');$q->execute([$actionId]);$active=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r)$active[$r['day_id'].'|'.$r['station_id']]=json_decode((string)$r['active_slots_json'],true)?:[];
 foreach($days as &$day){$day['slots']=json_decode((string)$day['slots_json'],true)?:[];$day['matrix']=[];$day['open']=0;$day['required']=0;foreach($stations as $station){$keys=$active[$day['id'].'|'.$station['id']]??[];foreach($day['slots'] as $slot){$key=(string)($slot['key']??'');$isActive=in_array($key,$keys,true);$cellKey=$day['id'].'|'.$station['id'].'|'.$key;$count=$filled[$cellKey]['count']??0;$capacity=(int)$station['capacity'];$countForDisplay=min($capacity,$count);if($isActive){$requiredTotal+=$capacity;$openTotal+=max(0,$capacity-$countForDisplay);$day['required']+=$capacity;$day['open']+=max(0,$capacity-$countForDisplay);}$day['matrix'][$station['id']][$key]=['active'=>$isActive,'filled'=>$countForDisplay,'actual'=>$count,'capacity'=>$capacity,'people'=>$filled[$cellKey]['people']??'','state'=>!$isActive?'inactive':($countForDisplay===0?'empty':($countForDisplay<$capacity?'partial':'full'))];}}}unset($day);
}
$weekday=['Monday'=>'Montag','Tuesday'=>'Dienstag','Wednesday'=>'Mittwoch','Thursday'=>'Donnerstag','Friday'=>'Freitag','Saturday'=>'Samstag','Sunday'=>'Sonntag'];
