.helper-wrap{max-width:1450px;margin:24px auto}.helper-card{background:#fff;border-radius:12px;padding:20px;margin:18px 0;box-shadow:0 2px 12px #0000000d}.helper-action-meta{display:flex;flex-wrap:wrap;gap:10px 22px;color:#667085}.helper-description{margin:10px 0 0;color:#475467}.helper-tag{display:inline-block;border-radius:20px;padding:5px 11px;font-size:.9rem;font-weight:650}.helper-tag.red{background:#fde2e2;color:#a12626}.helper-tag.yellow{background:#fff1c7;color:#80520a}.helper-tag.green{background:#d9f2df;color:#176b35}.helper-btn{border:0;border-radius:7px;padding:9px 13px;text-decoration:none;display:inline-flex;align-items:center;gap:7px;background:#e9edf2;color:#244e79}.helper-muted{color:#667085;font-size:.9rem}.day-toggle{display:flex;align-items:center;justify-content:space-between;gap:12px;cursor:pointer;list-style:none}.day-toggle::-webkit-details-marker{display:none}.day-toggle::after{content:'\f078';font-family:'Font Awesome 6 Free';font-weight:900;color:#667085;font-size:.85rem;transition:transform .15s}.day-panel[open]>.day-toggle::after{transform:rotate(180deg)}.day-title{font-size:1.08rem;margin:0}.day-tag{white-space:nowrap}.day-content{margin-top:16px}.matrix-scroll{overflow-x:auto}.matrix{width:100%;border-collapse:separate;border-spacing:5px;min-width:620px}.matrix th{font-size:.88rem;color:#475467;text-align:center;padding:8px;min-width:110px}.matrix th:first-child{text-align:left;min-width:115px}.matrix td{padding:0;text-align:center}.slot-name{font-weight:650;color:#344054;white-space:nowrap;padding:9px 8px!important;text-align:left!important}.cell{display:block;border-radius:7px;padding:11px 8px;text-decoration:none;color:#253247;font-weight:700;border:1px solid #0000000a;min-height:42px;box-sizing:border-box}.cell.full{background:#d9f2df}.cell.partial{background:#fff1c7}.cell.empty{background:#fde2e2}.cell.inactive{background:#eceff2;color:#98a2b3;font-weight:400}.cell:hover:not(.inactive){filter:brightness(.97);outline:2px solid #244e79;outline-offset:1px}.cell-detail{margin:5px 0 0;text-align:left}.cell-detail summary{cursor:pointer;list-style:none}.cell-detail summary::-webkit-details-marker{display:none}.cell-detail[open]{position:relative}.cell-detail-body{position:absolute;z-index:5;top:calc(100% + 5px);left:50%;transform:translateX(-50%);width:min(310px,75vw);background:#fff;border:1px solid #d9dee5;border-radius:9px;padding:12px;text-align:left;box-shadow:0 8px 24px #0002;font-weight:400}.cell-detail-body strong{display:block;margin-bottom:7px}.person{padding:7px 0;border-top:1px solid #edf0f2;font-size:.9rem}.person:first-of-type{border-top:0}.person small{display:block;color:#667085;overflow-wrap:anywhere}.empty-detail{color:#667085;font-size:.9rem}.no-action{padding:18px;color:#667085}
