</style></head><body><div class="container wrap"><header class="app-page-header"><h1>Helferlisten – Belegung</h1><?php require $root.'/includes/navigation.php';?></header><main class="helper-wrap"><p><a href="helferlisten.php"><i class="fa-solid fa-arrow-left"></i> Zurück zur Helferlisten-Übersicht</a></p>
<?php if(!$action):?><section class="helper-card no-action">Die angegebene Helferaktion wurde nicht gefunden.</section><?php else:?>
<section class="helper-card"><div><h2><?=hh($action['title'])?></h2><div class="helper-action-meta"><span><i class="fa-regular fa-calendar"></i> <?=date('d.m.Y',strtotime($action['start_date']))?> – <?=date('d.m.Y',strtotime($action['end_date']))?></span><span class="helper-tag <?=$openTotal===0?'green':($openTotal<=3?'yellow':'red')?>">Noch <?=$openTotal?>/<?=$requiredTotal?> Schichten zu besetzen</span></div><?php if($action['description']):?><p class="helper-description"><?=nl2br(hh($action['description']))?></p><?php endif;?></div></section>
<?php if(!$days):?><section class="helper-card no-action">Für diese Aktion sind keine Veranstaltungstage angelegt.</section><?php else:foreach($days as $day):?><details class="helper-card day-panel"><summary class="day-toggle"><h3 class="day-title"><?=hh($weekday[date('l',strtotime($day['event_date']))]??'')?> · <?=date('d.m.Y',strtotime($day['event_date']))?></h3><span class="helper-tag day-tag <?=$day['open']===0?'green':($day['open']<=3?'yellow':'red')?>">Noch <?=$day['open']?>/<?=$day['required']?> Schichten zu besetzen</span></summary><div class="day-content"><?php if(!$stations):?><p class="helper-muted">Für diese Aktion sind noch keine Stationen angelegt.</p><?php else:?><div class="matrix-scroll"><table class="matrix"><thead><tr><th>Zeitfenster</th><?php foreach($stations as $station):?><th><?=hh($station['name'])?></th><?php endforeach;?></tr></thead><tbody><?php foreach($day['slots'] as $slot):?><tr><th class="slot-name"><?=hh($slot['label']??$slot['key']??'')?></th><?php foreach($stations as $station):$cell=$day['matrix'][$station['id']][$slot['key']]??['active'=>false,'state'=>'inactive','filled'=>0,'capacity'=>(int)$station['capacity'],'people'=>'','actual'=>0];?><td><?php if(!$cell['active']):?><span class="cell inactive" title="Station in diesem Zeitfenster nicht aktiv">—</span><?php else:?><details class="cell-detail"><summary class="cell <?=$cell['state']?>" title="Belegungsdetails anzeigen"><?=$cell['filled']?>/<?=$cell['capacity']?></summary><div class="cell-detail-body"><strong><?=hh($station['name'])?> · <?=hh($slot['label']??$slot['key'])?></strong><div class="helper-muted"><?=date('d.m.Y',strtotime($day['event_date']))?> · <?=$cell['actual']?> Anmeldung(en) für <?=$cell['capacity']?> benötigte Person(en)</div><?php if($cell['people']!==''):foreach(explode("\n",$cell['people']) as $person):$parts=explode("\t",$person,2);?><div class="person"><?=hh($parts[0]??'')?><small><?=hh($parts[1]??'')?></small></div><?php endforeach;else:?><p class="empty-detail">Noch keine Anmeldungen vorhanden.</p><?php endif;?></div></details><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></details><?php endforeach;endif;?>
<?php endif;?></main></div></body></html>
